-- Generated by npm run store-ops:sql. Do not edit this file directly.
-- Run this ENTIRE file once in Supabase SQL Editor as the postgres role.
-- Creates missing operations base tables, then applies all operations repairs.
-- Existing records are retained. No attendance migrations or scheduler are run.
-- Requires the existing attendance notification/device migration.
BEGIN;
SET LOCAL search_path = public, extensions;
DO $install_prerequisites$
DECLARE missing_tables text;
BEGIN
 SELECT string_agg(name, ', ' ORDER BY name) INTO missing_tables
 FROM unnest(ARRAY['public.profiles','public.stores','storage.objects','storage.buckets',
  'public.attendance_notification_devices','hrm_private.attendance_notification_keys']) AS required(name)
 WHERE to_regclass(name) IS NULL;
 IF missing_tables IS NOT NULL THEN
  RAISE EXCEPTION USING MESSAGE='Required existing application tables are missing: ' || missing_tables,
   HINT='Use the intended Supabase project. For missing attendance notification tables, apply the existing attendance migrations through 20261124094512_attendance_reminders.sql first.';
 END IF;
 IF to_regprocedure('store_ops_private.guard_record()') IS NOT NULL
    OR to_regclass('public.checklist_template_items') IS NOT NULL
    OR to_regclass('public.store_operation_events') IS NOT NULL THEN
  RAISE EXCEPTION USING MESSAGE='Store Operations repair migrations are already installed or partially installed.',
   HINT='Apply only the remaining versioned migrations in order. This recovery bundle is for an installation with no successfully applied Store Operations repair migrations.';
 END IF;
END $install_prerequisites$;

-- Source: supabase/migrations/002_damage_reports.sql
-- Add manager role to profiles
ALTER TABLE profiles
  DROP CONSTRAINT IF EXISTS profiles_role_check;

ALTER TABLE profiles
  ADD CONSTRAINT profiles_role_check
  CHECK (role IN ('admin', 'manager', 'employee'));

-- Damage Types
DO $$ BEGIN
  CREATE TYPE damage_type AS ENUM (
    'Broken',
    'Leaking',
    'Expired',
    'Packaging Damage',
    'Customer Damage',
    'Supplier Damage',
    'Missing Item',
    'Tester Finished'
  );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE damage_report_status AS ENUM (
    'pending',
    'approved',
    'rejected',
    'archived'
  );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- damage_reports
CREATE TABLE IF NOT EXISTS damage_reports (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  barcode TEXT NOT NULL,
  product_name TEXT NOT NULL,
  brand TEXT,
  shade TEXT,
  batch TEXT,
  mrp DECIMAL(10,2),
  quantity INTEGER NOT NULL DEFAULT 1,
  damage_type damage_type NOT NULL,
  description TEXT,
  reported_by UUID NOT NULL REFERENCES profiles(id),
  store_id UUID REFERENCES stores(id),
  status damage_report_status NOT NULL DEFAULT 'pending',
  reviewed_by UUID REFERENCES profiles(id),
  reviewed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- damage_images
CREATE TABLE IF NOT EXISTS damage_images (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  damage_report_id UUID NOT NULL REFERENCES damage_reports(id) ON DELETE CASCADE,
  url TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- damage_comments
CREATE TABLE IF NOT EXISTS damage_comments (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  damage_report_id UUID NOT NULL REFERENCES damage_reports(id) ON DELETE CASCADE,
  comment TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_damage_reports_status ON damage_reports(status);
CREATE INDEX IF NOT EXISTS idx_damage_reports_reported_by ON damage_reports(reported_by);
CREATE INDEX IF NOT EXISTS idx_damage_reports_product_name ON damage_reports(product_name);
CREATE INDEX IF NOT EXISTS idx_damage_reports_barcode ON damage_reports(barcode);
CREATE INDEX IF NOT EXISTS idx_damage_reports_created_at ON damage_reports(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_damage_images_report ON damage_images(damage_report_id);
CREATE INDEX IF NOT EXISTS idx_damage_comments_report ON damage_comments(damage_report_id);

-- RLS
ALTER TABLE damage_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE damage_images ENABLE ROW LEVEL SECURITY;
ALTER TABLE damage_comments ENABLE ROW LEVEL SECURITY;

-- Drop existing policies if any
DROP POLICY IF EXISTS "Everyone can view damage reports" ON damage_reports;
DROP POLICY IF EXISTS "Employees can create damage reports" ON damage_reports;
DROP POLICY IF EXISTS "Admin/Manager can update damage reports" ON damage_reports;
DROP POLICY IF EXISTS "Admin can delete damage reports" ON damage_reports;
DROP POLICY IF EXISTS "Everyone can view damage images" ON damage_images;
DROP POLICY IF EXISTS "Authenticated users can add images" ON damage_images;
DROP POLICY IF EXISTS "Admin can delete images" ON damage_images;
DROP POLICY IF EXISTS "Everyone can view damage comments" ON damage_comments;
DROP POLICY IF EXISTS "Authenticated users can add comments" ON damage_comments;
DROP POLICY IF EXISTS "Admin can delete comments" ON damage_comments;

-- damage_reports policies
CREATE POLICY "Everyone can view damage reports"
  ON damage_reports FOR SELECT
  USING (true);

CREATE POLICY "Employees can create damage reports"
  ON damage_reports FOR INSERT
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'manager', 'employee'))
  );

CREATE POLICY "Admin/Manager can update damage reports"
  ON damage_reports FOR UPDATE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'manager'))
  );

CREATE POLICY "Admin can delete damage reports"
  ON damage_reports FOR DELETE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  );

-- damage_images policies
CREATE POLICY "Everyone can view damage images"
  ON damage_images FOR SELECT
  USING (true);

CREATE POLICY "Authenticated users can add images"
  ON damage_images FOR INSERT
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid())
  );

CREATE POLICY "Admin can delete images"
  ON damage_images FOR DELETE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  );

-- damage_comments policies
CREATE POLICY "Everyone can view damage comments"
  ON damage_comments FOR SELECT
  USING (true);

CREATE POLICY "Authenticated users can add comments"
  ON damage_comments FOR INSERT
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid())
  );

CREATE POLICY "Admin can delete comments"
  ON damage_comments FOR DELETE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  );

-- updated_at trigger
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ language 'plpgsql';

DROP TRIGGER IF EXISTS update_damage_reports_updated_at ON damage_reports;
CREATE TRIGGER update_damage_reports_updated_at
  BEFORE UPDATE ON damage_reports
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

-- Source: supabase/migrations/003_daily_checklist.sql
-- Checklist Templates
CREATE TABLE IF NOT EXISTS checklist_templates (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('opening', 'closing')),
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- Daily Checklists (one per day/type)
CREATE TABLE IF NOT EXISTS daily_checklists (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  template_id UUID NOT NULL REFERENCES checklist_templates(id),
  type TEXT NOT NULL CHECK (type IN ('opening', 'closing')),
  date DATE NOT NULL DEFAULT CURRENT_DATE,
  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'completed', 'missed')),
  completed_by UUID REFERENCES profiles(id),
  completed_at TIMESTAMPTZ,
  photo_url TEXT,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- Checklist Items (copied from template when checklist is started)
CREATE TABLE IF NOT EXISTS daily_checklist_items (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  daily_checklist_id UUID NOT NULL REFERENCES daily_checklists(id) ON DELETE CASCADE,
  label TEXT NOT NULL,
  is_completed BOOLEAN DEFAULT false,
  completed_by UUID REFERENCES profiles(id),
  completed_at TIMESTAMPTZ,
  photo_url TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_checklist_templates_type ON checklist_templates(type);
CREATE INDEX IF NOT EXISTS idx_daily_checklists_date ON daily_checklists(date);
CREATE INDEX IF NOT EXISTS idx_daily_checklists_type ON daily_checklists(type);
CREATE INDEX IF NOT EXISTS idx_daily_checklists_status ON daily_checklists(status);
CREATE INDEX IF NOT EXISTS idx_daily_checklist_items_checklist ON daily_checklist_items(daily_checklist_id);
CREATE INDEX IF NOT EXISTS idx_daily_checklist_items_status ON daily_checklist_items(daily_checklist_id, is_completed);

-- RLS
ALTER TABLE checklist_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE daily_checklists ENABLE ROW LEVEL SECURITY;
ALTER TABLE daily_checklist_items ENABLE ROW LEVEL SECURITY;

-- Drop existing policies
DROP POLICY IF EXISTS "Everyone can view checklist templates" ON checklist_templates;
DROP POLICY IF EXISTS "Admin/Manager can manage templates" ON checklist_templates;
DROP POLICY IF EXISTS "Admin/Manager can update templates" ON checklist_templates;
DROP POLICY IF EXISTS "Admin can delete templates" ON checklist_templates;
DROP POLICY IF EXISTS "Everyone can view daily checklists" ON daily_checklists;
DROP POLICY IF EXISTS "Authenticated users can create daily checklists" ON daily_checklists;
DROP POLICY IF EXISTS "Employees can update own checklists" ON daily_checklists;
DROP POLICY IF EXISTS "Users can update own checklists" ON daily_checklists;
DROP POLICY IF EXISTS "Admin can delete daily checklists" ON daily_checklists;
DROP POLICY IF EXISTS "Everyone can view checklist items" ON daily_checklist_items;
DROP POLICY IF EXISTS "Authenticated users can manage items" ON daily_checklist_items;
DROP POLICY IF EXISTS "Users can update items" ON daily_checklist_items;
DROP POLICY IF EXISTS "Admin can delete items" ON daily_checklist_items;

-- Templates policies
CREATE POLICY "Everyone can view checklist templates"
  ON checklist_templates FOR SELECT
  USING (true);

CREATE POLICY "Admin/Manager can manage templates"
  ON checklist_templates FOR INSERT
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'manager'))
  );

CREATE POLICY "Admin/Manager can update templates"
  ON checklist_templates FOR UPDATE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'manager'))
  );

CREATE POLICY "Admin can delete templates"
  ON checklist_templates FOR DELETE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  );

-- Daily checklists policies
CREATE POLICY "Everyone can view daily checklists"
  ON daily_checklists FOR SELECT
  USING (true);

CREATE POLICY "Authenticated users can create daily checklists"
  ON daily_checklists FOR INSERT
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid())
  );

CREATE POLICY "Users can update own checklists"
  ON daily_checklists FOR UPDATE
  USING (
    auth.uid() = created_by OR
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'manager'))
  );

CREATE POLICY "Admin can delete daily checklists"
  ON daily_checklists FOR DELETE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  );

-- Checklist items policies
CREATE POLICY "Everyone can view checklist items"
  ON daily_checklist_items FOR SELECT
  USING (true);

CREATE POLICY "Authenticated users can manage items"
  ON daily_checklist_items FOR INSERT
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid())
  );

CREATE POLICY "Users can update items"
  ON daily_checklist_items FOR UPDATE
  USING (
    auth.uid() = created_by OR
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'manager'))
  );

CREATE POLICY "Admin can delete items"
  ON daily_checklist_items FOR DELETE
  USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  );

-- updated_at trigger for all three tables
DROP TRIGGER IF EXISTS update_checklist_templates_updated_at ON checklist_templates;
CREATE TRIGGER update_checklist_templates_updated_at
  BEFORE UPDATE ON checklist_templates
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS update_daily_checklists_updated_at ON daily_checklists;
CREATE TRIGGER update_daily_checklists_updated_at
  BEFORE UPDATE ON daily_checklists
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS update_daily_checklist_items_updated_at ON daily_checklist_items;
CREATE TRIGGER update_daily_checklist_items_updated_at
  BEFORE UPDATE ON daily_checklist_items
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

-- Source: supabase/migrations/004_remaining_modules.sql
-- ============================================================
-- MODULE 1: SHELF INSPECTION
-- ============================================================

CREATE TABLE IF NOT EXISTS store_sections (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS shelf_inspections (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  section_id UUID NOT NULL REFERENCES store_sections(id),
  employee_id UUID NOT NULL REFERENCES profiles(id),
  status TEXT NOT NULL DEFAULT 'good' CHECK (status IN ('good','needs_restock','dirty','wrong_display','missing_tester','missing_price_tag','damaged_display')),
  notes TEXT,
  reviewed_by UUID REFERENCES profiles(id),
  reviewed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS inspection_images (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  inspection_id UUID NOT NULL REFERENCES shelf_inspections(id) ON DELETE CASCADE,
  url TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS inspection_comments (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  inspection_id UUID NOT NULL REFERENCES shelf_inspections(id) ON DELETE CASCADE,
  comment TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- ============================================================
-- MODULE 3: TESTER MANAGEMENT
-- ============================================================

CREATE TABLE IF NOT EXISTS testers (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  product_name TEXT NOT NULL,
  brand TEXT,
  shade TEXT,
  opened_date DATE,
  expiry_date DATE,
  condition TEXT DEFAULT 'good' CHECK (condition IN ('good','fair','poor','finished')),
  remaining_percentage INTEGER DEFAULT 100 CHECK (remaining_percentage >= 0 AND remaining_percentage <= 100),
  needs_replacement BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS tester_logs (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  tester_id UUID NOT NULL REFERENCES testers(id) ON DELETE CASCADE,
  action TEXT NOT NULL,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- ============================================================
-- MODULE 5: TASK MANAGEMENT
-- ============================================================

CREATE TABLE IF NOT EXISTS tasks (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  assigned_to UUID REFERENCES profiles(id),
  assigned_by UUID REFERENCES profiles(id),
  priority TEXT DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  due_date TIMESTAMPTZ,
  status TEXT DEFAULT 'pending' CHECK (status IN ('pending','in_progress','completed','cancelled')),
  category TEXT CHECK (category IN ('restock','cleaning','inventory','maintenance','promotion','general')),
  is_recurring BOOLEAN DEFAULT false,
  recurrence_rule TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS task_comments (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  comment TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS task_attachments (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  url TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- ============================================================
-- MODULE 6: STORE AUDITS
-- ============================================================

CREATE TABLE IF NOT EXISTS audit_templates (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT CHECK (category IN ('display','cleanliness','staff','lighting','product_placement','price_tags','promotions','safety')),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS audit_questions (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  template_id UUID NOT NULL REFERENCES audit_templates(id) ON DELETE CASCADE,
  question TEXT NOT NULL,
  max_score INTEGER DEFAULT 5,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS audits (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  template_id UUID NOT NULL REFERENCES audit_templates(id),
  store_id UUID REFERENCES stores(id),
  conducted_by UUID NOT NULL REFERENCES profiles(id),
  final_score DECIMAL(5,2),
  max_score DECIMAL(5,2),
  notes TEXT,
  status TEXT DEFAULT 'in_progress' CHECK (status IN ('in_progress','completed')),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS audit_answers (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  audit_id UUID NOT NULL REFERENCES audits(id) ON DELETE CASCADE,
  question_id UUID NOT NULL REFERENCES audit_questions(id),
  score INTEGER DEFAULT 0,
  comment TEXT,
  photo_url TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- ============================================================
-- MODULE 7: INCIDENT REPORTS
-- ============================================================

CREATE TABLE IF NOT EXISTS incidents (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  incident_type TEXT NOT NULL CHECK (incident_type IN ('customer_complaint','power_failure','internet_down','theft','broken_fixture','emergency','medical','other')),
  priority TEXT DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  status TEXT DEFAULT 'open' CHECK (status IN ('open','in_progress','resolved','closed')),
  assigned_to UUID REFERENCES profiles(id),
  store_id UUID REFERENCES stores(id),
  voice_note_url TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS incident_images (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  incident_id UUID NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  url TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS incident_comments (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  incident_id UUID NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  comment TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- ============================================================
-- MODULE 8: RESTOCKING
-- ============================================================

CREATE TABLE IF NOT EXISTS restock_requests (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  status TEXT DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','completed')),
  notes TEXT,
  supplier_notes TEXT,
  approved_by UUID REFERENCES profiles(id),
  approved_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

CREATE TABLE IF NOT EXISTS restock_items (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  restock_request_id UUID NOT NULL REFERENCES restock_requests(id) ON DELETE CASCADE,
  barcode TEXT NOT NULL,
  product_name TEXT NOT NULL,
  brand TEXT,
  quantity_needed INTEGER NOT NULL DEFAULT 1,
  quantity_approved INTEGER,
  supplier_notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID NOT NULL REFERENCES profiles(id)
);

-- ============================================================
-- MODULE 9: NOTIFICATIONS LOG
-- ============================================================

CREATE TABLE IF NOT EXISTS notification_log (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID REFERENCES profiles(id),
  title TEXT NOT NULL,
  body TEXT,
  type TEXT,
  link TEXT,
  is_read BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES profiles(id)
);

-- Existing installations may already have the earlier table definitions.
ALTER TABLE notification_log ADD COLUMN IF NOT EXISTS created_by UUID REFERENCES profiles(id);
ALTER TABLE notification_log ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();
ALTER TABLE audit_answers ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

